def _ljPairParameters(self, type1, type2):
    """Get the Lennard-Jones parameters describing the interaction between two atom types.

    An explicit [ nonbond_params ] entry takes precedence over the combination rule, just
    as it does in Gromacs.  The values are returned in the convention the topology file
    uses for the current combination rule: (c6, c12) for combination rule 1, and
    (sigma, epsilon) for combination rules 2 and 3.
    """
    key = tuple(sorted((type1, type2)))
    if key in self._nonbondTypes:
        fields = self._nonbondTypes[key]
        return (float(fields[3]), float(fields[4]))
    params1 = self._atomTypes[type1]
    params2 = self._atomTypes[type2]
    v1, w1 = (float(params1[6]), float(params1[7]))
    v2, w2 = (float(params2[6]), float(params2[7]))
    w = math.sqrt(abs(w1*w2))
    if self._defaults[1] == '2':
        # Only combination rule 2 combines the first parameter (sigma) arithmetically.
        return (0.5*(v1+v2), w)
    return (math.sqrt(v1*v2), w)

def _ljExceptionParameters(self, v, w):
    """Convert a pair of Lennard-Jones parameters written in the convention of the topology
    file to the convention used for the exceptions of this System.

    For combination rule 2 the parameters are sigma and epsilon, which a NonbondedForce
    exception can represent directly.  For combination rules 1 and 3 they are converted to
    c6 and c12 coefficients, which are the parameters of the CustomBondForce that computes
    the exceptions in that case.
    """
    if self._defaults[1] == '2':
        return (v, w)
    if self._defaults[1] == '1':
        # The parameters already are c6 and c12.
        return (v, w)
    return (4*w*v**6, 4*w*v**12)

def _generatedPairParameters(self, type1, type2, fudgeLJ):
    """Generate the Lennard-Jones parameters of a 1-4 pair from the nonbonded parameters of
    the two atom types, as Gromacs does when gen-pairs is set to "yes".

    fudgeLJ scales the strength of the interaction but not the size of the particles, so it
    multiplies epsilon for combination rule 2 and both c6 and c12 for the other rules.  The
    values are returned in the convention used for the exceptions of this System.
    """
    params = self._ljExceptionParameters(*self._ljPairParameters(type1, type2))
    if self._defaults[1] == '2':
        return (params[0], fudgeLJ*params[1])
    return (fudgeLJ*params[0], fudgeLJ*params[1])

